import sys
from math import log10

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    L_str = data[0].strip()
    R_str = data[1].strip()

    L = int(L_str)
    R = int(R_str)

    if L == R:
        print(1)
        print("0 1")
        return

    def get_level(idx):
        if idx == 0:
            return 0
        val = idx - 1
        if val < 10:
            return 0
        s = str(val)
        length = len(s)
        k = 1
        while True:
            seg_len = 10 ** (2 ** (k - 1))
            if seg_len > length:
                break
            if seg_len == length:
                return k
            k += 1
        return 0

    def get_block_start(idx, level):
        if level == 0:
            return idx
        seg_len = 10 ** (2 ** (level - 1))
        return ((idx - 1) // seg_len) * seg_len + 1

    def get_block_end(idx, level):
        if level == 0:
            return 1
        seg_len = 10 ** (2 ** (level -1))
        start = get_block_start(idx, level)
        return start + seg_len - 1

    def is_aligned(idx, level):
        if level == 0:
            return True
        seg_len = 10 ** (2 ** (level -))
        return (idx - 1) % seg_len == 0

    def find_max_level_for_range(start, end):
        length = end - start + 1
        k = 0
        best_k = 0
        while True:
            seg_len = 10 ** (1 << (k - 1)) if k > 0 else 1
            if seg_len > length:
                break
            if is_aligned(start, k):
                end_check = get_block_end(start, k)
                if end_check == end:
                    best_k = k
            k += 1
            if k > 60:
                break
        return best_k

    def decompose(l, r):
        if l > r:
            return []
        if l == r:
            return [(0, 1)]

        res = []
        current_l = l

        while current_l <= r:
            if current_l == r:
                res.append((0, 1))
                current_l += 1
                continue

            best_level = 0
            best_r = current_l

            k = 0
            while True:
                seg_len = 10 ** (1 << (k - 1 if k > 0 else 0))
                if seg_len > (r - current_l + 1):
                    break
                if (current_l - 1) % seg_len == 0:
                    candidate_r = current_l + seg_len - 1
                    if candidate_r <= r:
                        if candidate_r > best_r:
                            best_level = k
                            best_r = candidate_r
                k += 1
                if k > 60:
                    break

            res.append((best_level, best_r - current_l + 1))
            current_l = best_r + 1

        return res

    raw_blocks = decompose(L, R)
    compressed = []
    if raw_blocks:
        curr_t, curr_c = raw_blocks[0]
        for t, c in raw_blocks[1:]:
            if t == curr_t:
                curr_c += c
            else:
                compressed.append((curr_t, curr_c))
                curr_t, curr_c = t, c
        compressed.append((curr_t, curr_c))

    print(len(compressed))
    for t, c in compressed:
        print(f"{t} {c}")

if __name__ == "__main__":
    solve()
